            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "jsonrpc", "2.0" },
                { "id", requestId },
                { "method", "public/auth" },
                { "params", paramsAuth },
            };
            future = client.reusableFuture(messageHash);
            this.watch(url, messageHash, this.extend(request, paramsResolved), messageHash);
